// Package store opens the panel's SQLite database and applies migrations.
//
// Queries live in queries/*.sql and are generated by sqlc into dbq/: no code
// builds SQL from strings.
package store

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"os"
	"path/filepath"
	"time"

	"github.com/pressly/goose/v3"
	_ "modernc.org/sqlite" // "sqlite" driver, pure Go, no CGO

	"github.com/JuniorCarlini/hangar/internal/store/dbq"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

// Store is the panel database access.
type Store struct {
	DB *sql.DB
	Q  *dbq.Queries
}

// Open opens (or creates) the database at path with mode 0600 and applies
// pending migrations. Before migrating a database that already has data, it
// keeps a copy in backupDir.
func Open(ctx context.Context, path, backupDir string, log *slog.Logger) (*Store, error) {
	if err := ensureFile(path); err != nil {
		return nil, err
	}

	// auto_vacuum only takes effect if set before the first table, so it comes
	// first. journal_size_limit keeps the -wal file from growing huge after a
	// write spike.
	dsn := "file:" + path +
		"?_pragma=auto_vacuum(INCREMENTAL)" +
		"&_pragma=journal_mode(WAL)" +
		"&_pragma=journal_size_limit(67108864)" +
		"&_pragma=foreign_keys(ON)" +
		"&_pragma=busy_timeout(5000)" +
		"&_pragma=synchronous(NORMAL)" +
		"&_txlock=immediate"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	// A single writer: SQLite serializes writes anyway, and one connection
	// avoids SQLITE_BUSY without retry logic scattered around.
	db.SetMaxOpenConns(1)

	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("open database: %w", err)
	}

	if err := migrate(ctx, db, path, backupDir, log); err != nil {
		_ = db.Close()
		return nil, err
	}

	return &Store{DB: db, Q: dbq.New(db)}, nil
}

// Close closes the database.
func (s *Store) Close() error { return s.DB.Close() }

func ensureFile(path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("create database directory: %w", err)
	}
	// Creating the file before SQLite guarantees 0600 regardless of umask;
	// the -wal and -shm files inherit the database's permissions.
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600) //nolint:gosec // path derived from the configured data_dir
	if err != nil {
		return fmt.Errorf("create database: %w", err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("create database: %w", err)
	}
	return os.Chmod(path, 0o600)
}

func migrate(ctx context.Context, db *sql.DB, path, backupDir string, log *slog.Logger) error {
	migrations, err := fs.Sub(migrationsFS, "migrations")
	if err != nil {
		return err
	}
	provider, err := goose.NewProvider(goose.DialectSQLite3, db, migrations)
	if err != nil {
		return fmt.Errorf("prepare migrations: %w", err)
	}

	pending, err := provider.HasPending(ctx)
	if err != nil {
		return fmt.Errorf("check migrations: %w", err)
	}
	if !pending {
		return nil
	}

	current, err := provider.GetDBVersion(ctx)
	if err != nil {
		return fmt.Errorf("check migrations: %w", err)
	}
	if current > 0 {
		backup, err := backupBeforeMigrate(ctx, db, backupDir)
		if err != nil {
			return err
		}
		log.Info("database copied before migrating", "file", backup)
	}

	results, err := provider.Up(ctx)
	if err != nil {
		return fmt.Errorf("apply migrations to %s: %w", path, err)
	}
	for _, r := range results {
		log.Info("migration applied", "version", r.Source.Version, "file", r.Source.Path)
	}
	return nil
}

func backupBeforeMigrate(ctx context.Context, db *sql.DB, dir string) (string, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", fmt.Errorf("create backup directory: %w", err)
	}
	dest := filepath.Join(dir, "pre-migracao-"+time.Now().UTC().Format("20060102T150405Z")+".db")
	if _, err := os.Stat(dest); err == nil {
		return "", errors.New("pre-migration copy already exists: " + dest)
	}
	// VACUUM INTO produces a consistent copy even with the database open.
	if _, err := db.ExecContext(ctx, "VACUUM INTO ?", dest); err != nil {
		return "", fmt.Errorf("copy database before migrating: %w", err)
	}
	if err := os.Chmod(dest, 0o600); err != nil {
		return "", err
	}
	return dest, nil
}
